# Construct the 27x27 output using the demonstrated scaling/reflection rule.
grid = [[4 for _ in range(27)] for _ in range(27)]
for i in range(27):
    grid[13][i] = 1
    grid[i][13] = 1
# Top-left reference motif (unchanged)
for r in (5, 6):
    for c in (4, 5): grid[r][c] = 7
    for c in (6, 7): grid[r][c] = 2
for r in (7, 8):
    for c in (6, 7): grid[r][c] = 3
# Other original 2 blocks
blocks = {'TR': (3, 20, 1), 'BL': (20, 5, 2), 'BR': (19, 18, 3)}
for r0,c0,n in blocks.values():
    for r in range(r0,r0+n):
        for c in range(c0,c0+n): grid[r][c] = 2
# Decorations copied from TL motif, scaled to target size and reflected by quadrant.
# All patches here are 2x2 in the template, so the output patch is n x n.
# TR: 7 right, 3 below
r0,c0,n = blocks['TR']
for r in range(r0,r0+n):
    for c in range(c0+n,c0+2*n): grid[r][c] = 7
for r in range(r0+n,r0+2*n):
    for c in range(c0,c0+n): grid[r][c] = 3
# BL: 7 left, 3 above
r0,c0,n = blocks['BL']
for r in range(r0,r0+n):
    for c in range(c0-n,c0): grid[r][c] = 7
for r in range(r0-n,r0):
    for c in range(c0,c0+n): grid[r][c] = 3
# BR: 7 right, 3 above
r0,c0,n = blocks['BR']
for r in range(r0,r0+n):
    for c in range(c0+n,c0+2*n): grid[r][c] = 7
for r in range(r0-n,r0):
    for c in range(c0,c0+n): grid[r][c] = 3
print('\n'.join(' '.join(map(str,row)) for row in grid))
import json
print('JSON:', json.dumps(grid, separators=(',',':')))
